from pathlib import Path
import hashlib,json
import xml.etree.ElementTree as E

ROOT=Path(__file__).resolve().parents[2];O=Path(__file__).resolve().parent
Q=ROOT/'tools/nsp-next-corrections-20261022'
load=lambda p:json.loads(p.read_text())
write=lambda n,a:(O/n).write_text(json.dumps(a,ensure_ascii=False,indent=2)+'\n')
packages=load(O/'CURRENT_CANDIDATE_PACKAGES.json')
source=load(O/'SOURCE_SHA256.json')
protected=load(O/'PRESERVATION_GATE.json')
live=load(O/'retention/native/PUBLIC_GET_RECEIPT.json')
assert len(live['files'])==11 and all(x['matches_repository_and_prior_audit']for x in live['files'])
write('PUBLIC_PRODUCT_GET_RECEIPT.json',live)

# Native PASS is associated with exact source SHA; an unrelated PDF hash is never sufficient.
native={}
for p in Q.rglob('report.xml'):
    rt=E.parse(p).getroot()
    if rt.get('status')!='PASS':continue
    for f in rt.findall('file'):
        r=f.find('result')
        if r is not None and f.get('status')=='PASS' and r.get('source_sha256'):
            native.setdefault(r.get('source_sha256'),[]).append(dict(job=rt.get('job'),kind='WORD_OPEN_EXPORT',receipt=str(p.relative_to(ROOT))))
    for c in rt.findall('check'):
        if c.get('name','').endswith(':source_unchanged') and c.get('pass','').lower()=='true':
            s=c.get('actual','')
            if len(s)==64:native.setdefault(s,[]).append(dict(job=rt.get('job'),kind='EXCEL_EXACT_SOURCE',receipt=str(p.relative_to(ROOT))))
free_native=[]
for pack in packages['free']:
    for member in pack['members']:
        if member['name'].endswith(('.docx','.xlsx')):
            assert member['sha256']in native,(pack['path'],member['name'])
            free_native.append(dict(package=pack['path'],file=member['name'],sha256=member['sha256'],evidence=native[member['sha256']]))
assert len(free_native)==12
write('CURRENT_FREE_NATIVE_SHA_LINKS.json',free_native)

